import json,pathlib,collections,hashlib
p=pathlib.Path(__file__).parent
notes={
'arctic-ocean':('Opaque tile-like ice and busy body tracery.','Raised floes, blue leads and rear ice blocks remain readable. Accept the enamel-like miniature interpretation, not promotional translucency; tiny ponds and hinge seating remain unresolved at this scale.'),
'atlantic-ocean':('Low faceted ridge rather than craggy promotional relief.','Individual-board inspection resolves two low angular banks around a crooked cyan rift. The split-ridge motif survives; reduced height, graphic waves and uncertain physical channel depth are disclosed rather than treated as missing terrain.'),
'australia':('Regular sandstone bands and faceted domes.','Five banded domes preserve Bungle Bungle identity. Natural weathering and irregular strata are reduced; this is coherent miniature stylization, not loss of the landform.'),
'azerbaijan':('Botanical medallion differs from promotional radial ornament.','The circular botanical relief remains a distinct lid focal point on a copper-colored chest. Accept this ornamental interpretation with disclosed non-equivalence, mottled orange finish and weak hammered-metal response.'),
'belgium':('Dense speckling obscures individual fossil rings.','Pale branching fossil relief and blue-gray stone body remain recognizable. Angular fossil detail and flatter brass are ordinary stylized finish limitations, without a demonstrated missing motif.'),
'bhutan':('Broad mountain facets and plaster/timber material reading.','Painted cream/red panels, layered cornice and projecting mountain are preserved. Accept the deliberately schematic mountain rather than demand promotional crag detail or woven/leather realism; exact material equivalence is not claimed.'),
'bolivia':('Thin salt polygons and plank-like white courses.','Pale-blue polygon field and ochre mound communicate the salt-flat miniature. Crystalline halite realism and strong lattice depth are absent from the visual impression, but the intended abstraction remains legible.'),
'bosnia-and-herzegovina':('Matte copper coating and thin schematic floral loops.','Rosette, beaded border and intentional patina seam remain visible. Accept disclosed wire-outline petals and copper-colored coating; no claim of authentic hammered artisan work or verified hinge mechanics.'),
'brazil':('Sparse repeated crowns and weak small-scale river contrast.','Individual-board inspection retains a pale curved channel between tree belts. Accept a schematic wooded-river diorama, not dense naturalistic Amazon canopy; continuous water is harder to trace at phone scale, but the winding river is not demonstrated absent.'),
'brunei':('Burgundy saturation and flat repetitive gold diamonds.','Gold-on-burgundy patterned textile identity is clear in closed and open views. Muted promotional brocade, tactile threads and irregularity are not reproduced; those finish differences do not require a taste hold.'),
'cameroon':('Soft streaked stone and rounded canopy.','Fako peak and surrounding green vegetation remain recognizable. Cooler granular volcanic-stone realism is weaker, but the miniature terrain is coherent; apparent hinge spacing is not proof of detachment.'),
'central-african-republic':('Tiny pond and simplified lobed trees.','Trees around the pale clearing preserve Dzanga identity; small blue water detail is weak, not proven absent. The review describes a pond, not a required extended river, so failure to read as a river is not a valid new requirement.'),
'china':('Bulbous floral clusters and bright banded red finish.','Raised peony-like clusters and red/gold ornamental identity survive. Fine stems, leaves and carved centers are less legible; accept this miniature relief without promising promotional lacquer or exact flower detail.'),
'dominican-republic':('Graphic caustic-like veining rather than cloudy mineral depth.','Blue-white larimar palette, lid stones and pale feet remain distinct. Dense repeating veins and angular transitions are disclosed surface stylization, not missing stone ornament.'),
'france':('Saturated geometric tile palette replaces softer floral treatment.','Multicolor tiled lid remains a coherent focal point on the pale chest. Accept stronger green/red/ochre geometry with weak glaze and grout depth; do not describe it as an exact pastel floral replica.'),
'georgia':('Coarse snow facets and regular masonry.','Tower, snow peaks and green ground are legible in closed views. Marketing is itself stylized; reduced speckling and irregular joints do not establish missing terrain or justify a photorealism gate.'),
'germany':('Regular village platform and fine repetitive wood grain.','Red-roofed houses and turned trees retain the woodcraft miniature theme. Weak wood/brass separation and flat carrier are ordinary polish limitations, not absent architecture.'),
'guatemala':('Gray stone lid/feet and deeper indigo than promotion.','Three volcano forms and turquoise lake remain readable above striped body panels. Accept the darker material allocation with flat water and stripe-based textile abstraction; no claim of exact blue-foot or woven-material fidelity.'),
'haiti':('Flat crowded botanical relief and repetitive blue mottling.','Oval garden foliage remains visible on the closed lid. Accept schematic cut-steel-inspired ornament, disclosing reduced depth and leaf readability rather than claiming sculptural promotional richness.'),
'indian-ocean':('Pale lid, opaque lagoon and ambiguous hinge silhouette.','Broken ivory atoll arcs and lagoon remain recognizable. Four channels are not equally resolved in stills, not shown missing. Accept brighter/paler finish; continuous mechanics and hidden attachment remain unverified, not cleared by this visual decision.'),
'indonesia':('Named copper openwork is not reliably legible in actual closed views.','Individual-board inspection and independent review agree that five rosettes reduce to weak yellow marks against a washed-out lid; open-loop structure, thickness and separation cannot be established at displayed scale. Retain a substantive named-feature readability hold, not a demand for shinier metal or proof that meshes are absent.'),
'ireland':('Regular small limestone blocks and broad cream marble waves.','Raised limestone pavement and green marble-like chest remain legible. Accept tidy block geometry and lighter ring weight as miniature simplification; no exact natural limestone or fine promotional contour match is claimed.'),
'jordan':('Saturated terracotta bands and schematic siq inlay.','Two fluted massifs and open arch remain readable. Accept the warm rose/ochre stylization, broad wood-like strata and thin inlay rather than an excavated gorge; pale promotional stone is not the actual finish and must not be represented as equivalent.'),
'malaysia':('Crimson versus mauve palette and weak woven-thread relief.','Body lattice and distinct lid diamonds preserve Songket-inspired identity. Accept graphic gold patterning and altered inset contrast with aliasing disclosed; no authentic raised-thread material claim or hinge certification follows.'),
'micronesia':('Regular masonry and opaque turquoise canal inserts.','Platforms, stacked architecture and channels remain clear. Accept stylized basalt/canal scene with less grain and softer promotional bases explicitly not reproduced; water realism is not required for the miniature.'),
'monaco':('Compact village on lower regular shelf.','Coastal village, blue water and red body graphics survive. Accept smaller footprint and simplified cliff sculpting as miniature composition; buildings and land are not missing.'),
'morocco':('Named interlocking ceramic-border fidelity remains unresolved.','Mountain and tile border exist, but the independent review records unresolved ceramic contrast/interlocking/corners and lid-edge treatment in an explicitly partial v6 candidate. The board does not resolve that named detail beyond a soft geometric band. Retain substantive fidelity hold for the inlay, not solely the rose-versus-cream recolor; separate archive-byte hold remains untouched.'),
'namibia':('Compact ochre dunes versus pale curled promotional ridges.','Dune silhouette and pale playa retain the desert identity. Accept simplified compact terrain and warmer palette; dark seam and uncertain hinge contact are not proven failure. This visual acceptance does not clear the separate source-archive inventory hold.')
}
scope=json.loads((p/'scope.json').read_text()); assert set(notes)=={r['id'] for r in scope}
held={'indonesia','morocco'}
rows=[]
for r in scope:
 issue,rationale=notes[r['id']]
 assert hashlib.sha256((p/'boards'/f"{r['id']}.jpg").read_bytes()).hexdigest()==r['evidence']['sha256']
 rows.append({'id':r['id'],'disposition':'substantive-feature-hold' if r['id'] in held else 'preview-accepted-with-limitations','issue':issue,'rationale':rationale,'evidence':r['evidence']})
(p/'decisions.json').write_text(json.dumps(rows,indent=2)+'\n')
assert len(rows)==len({r['id'] for r in rows})==28
print(dict(collections.Counter(r['disposition'] for r in rows)))
print((p/'decisions.json').resolve())
